import json,numpy as np
p='/app/output/run/peek'; m=json.load(open(p+'/meta.json'));cam='robot0_eye_in_hand'; c=m['cameras'][cam];K=np.array(c['intrinsic_cv']);T=np.array(c['cam2world_gl']);D=np.load(p+'/depth_'+cam+'.npy')[-1].astype(float)
def W(u,v):
 d=D[v,u]; q=np.array([(u-K[0,2])/K[0,0]*d,-(v-K[1,2])/K[1,1]*d,-d,1]);return (T@q)[:3]
for name,box in [('tan',(190,124,207,142)),('green',(205,60,229,106)),('surface',(130,130,175,160))]:
 x0,y0,x1,y1=box; ps=[]
 for v in range(y0,y1+1):
  for u in range(x0,x1+1):
   x=W(u,v)
   if np.isfinite(x).all():ps.append(x)
 a=np.array(ps);print(name,'n',len(a),'XYZ median',np.median(a,axis=0),'range',np.quantile(a,[.05,.95],axis=0))
print('eef',m['proprio']['now'][26:29]); print('eye cam',T[:3,3])
